Here is the root cause:
In amdgpu_device_gpu_recover(), the code accesses job->pasid after drm_sched_start() is called; drm_sched_start() may trigger the TDR workqueue to free the job, causing a use-after-free when job->pasid is read later.

Here is the patch:

 int amdgpu_device_gpu_recover(struct amdgpu_device *adev,
 			      struct amdgpu_job *job,
 			      struct amdgpu_reset_context *reset_context)
 {
 	struct list_head device_list;
 	bool job_signaled = false;
 	struct amdgpu_hive_info *hive = NULL;
 	int r = 0;
 	bool need_emergency_restart = false;
+	/* save the pasid here as the job may be freed before the end of the reset */
+	int pasid = job ? job->pasid : -EINVAL;

 	/*
 	 * If it reaches here because of hang/timeout and a RAS error is
 	 * detected at the same time, let RAS recovery take care of it.
 	 */
 	if (amdgpu_ras_is_err_state(adev, AMDGPU_RAS_BLOCK__ANY) &&
 	    !amdgpu_sriov_vf(adev) &&
 	    reset_context->src != AMDGPU_RESET_SRC_RAS) {
 		dev_dbg(adev->dev,
 			"Gpu recovery from source: %d yielding to RAS error recovery handling",
 			reset_context->src);
 		return 0;
 	}

 	/*
 	 * Special case: RAS triggered and full reset isn't supported
 	 */
 	need_emergency_restart = amdgpu_ras_need_emergency_restart(adev);

 	/*
 	 * Flush RAM to disk so that after reboot
 	 * the user can read log and see why the system rebooted.
 	 */
 	if (need_emergency_restart && amdgpu_ras_get_context(adev) &&
 		amdgpu_ras_get_context(adev)->reboot) {
 		dev_warn(adev->dev, "Emergency reboot.");

 		ksys_sync_helper();
 		emergency_restart();
 	}

 	dev_info(adev->dev, "GPU %s begin!. Source:  %d\n",
 		 need_emergency_restart ? "jobs stop" : "reset",
 		 reset_context->src);

 	if (!amdgpu_sriov_vf(adev))
 		hive = amdgpu_get_xgmi_hive(adev);
 	if (hive)
 		mutex_lock(&hive->hive_lock);

 	reset_context->job = job;
 	reset_context->hive = hive;
 	INIT_LIST_HEAD(&device_list);

 	amdgpu_device_recovery_prepare(adev, &device_list, hive);

 	if (!amdgpu_sriov_vf(adev)) {
 		r = amdgpu_device_health_check(&device_list);
 		if (r)
 			goto end_reset;
 	}

 	/* Cannot be called after locking reset domain */
 	amdgpu_ras_pre_reset(adev, &device_list);

 	/* We need to lock reset domain only once both for XGMI and single device */
 	amdgpu_device_recovery_get_reset_lock(adev, &device_list);

 	amdgpu_device_halt_activities(adev, job, reset_context, &device_list,
 				      hive, need_emergency_restart);
 	if (need_emergency_restart)
 		goto skip_sched_resume;
 	/*
 	 * Must check guilty signal here since after this point all old
 	 * HW fences are force signaled.
 	 *
 	 * job->base holds a reference to parent fence
 	 */
 	if (job && dma_fence_is_signaled(&job->hw_fence->base)) {
 		job_signaled = true;
 		dev_info(adev->dev, "Guilty job already signaled, skipping HW reset");
 		goto skip_hw_reset;
 	}

 	r = amdgpu_device_asic_reset(adev, &device_list, reset_context);
 	if (r)
 		goto reset_unlock;
 skip_hw_reset:
 	r = amdgpu_device_sched_resume(&device_list, reset_context, job_signaled);
 	if (r)
 		goto reset_unlock;
 skip_sched_resume:
 	amdgpu_device_gpu_resume(adev, &device_list, need_emergency_restart);
 reset_unlock:
 	amdgpu_device_recovery_put_reset_lock(adev, &device_list);
 	amdgpu_ras_post_reset(adev, &device_list);
 end_reset:
 	if (hive) {
 		mutex_unlock(&hive->hive_lock);
 		amdgpu_put_xgmi_hive(hive);
 	}

 	if (r)
 		dev_info(adev->dev, "GPU reset end with ret = %d\n", r);

 	atomic_set(&adev->reset_domain->reset_res, r);

 	if (!r) {
 		struct amdgpu_task_info *ti = NULL;

-		if (job)
-			ti = amdgpu_vm_get_task_info_pasid(adev, job->pasid);
+		/*
+		 * The job may already be freed at this point via the sched tdr workqueue so
+		 * use the cached pasid.
+		 */
+		if (pasid >= 0)
+			ti = amdgpu_vm_get_task_info_pasid(adev, pasid);

 		drm_dev_wedged_event(adev_to_drm(adev), DRM_WEDGE_RECOVERY_NONE,
 				     ti ? &ti->task : NULL);

 		amdgpu_vm_put_task_info(ti);
 	}

 	return r;
 }



